function i(t){if(t==null||isNaN(t))return"0 ₽";const r=Math.abs(t).toFixed(2).split(".");return r[0]=r[0].replace(/\B(?=(\d{3})+(?!\d))/g," "),(t<0?"-":"")+r.join(",")+" ₽"}function o(t){return t?new Date(t).toLocaleDateString("ru-RU",{day:"2-digit",month:"2-digit",year:"numeric"}):""}function a(t){return t==null?"0%":`${t>=0?"+":""}${t.toFixed(1)}%`}function u(t,r){let n;return(...e)=>{clearTimeout(n),n=setTimeout(()=>t(...e),r)}}export{o as a,a as b,u as d,i as f};
